const r = await tools.exec_command({cmd:"python3 - <<'PY'
from pathlib import Path
from collections import Counter
import h5py, numpy as np
root=Path('/app/data/Ephys_Behavior'); fs=sorted(root.glob('data_structure_*.mat'))
def chars(ds): return ''.join(chr(int(x)) for x in np.asarray(ds[()]).ravel(order='F') if int(x))
def ref_objs(f,ds):
 vals=np.asarray(ds[()]).ravel(order='F'); out=[]
 for r in vals:
  if isinstance(r,h5py.Reference) and r: out.append(f[r])
 return out
def strings(f,ds):
 if ds.dtype!=object: return [chars(ds)]
 out=[]
 for o in ref_objs(f,ds):
  out.append(chars(o) if isinstance(o,h5py.Dataset) and o.dtype!=object else '<nonchar>')
 return out
total_trials=rawclus=0; animals=Counter(); quals=Counter(); locs=Counter(); flags=Counter(); valid=Counter(); rows=[]
for p in fs:
 with h5py.File(p,'r') as f:
  n=int(f['obj/bp/Ntrials'][0,0]); total_trials+=n
  animal=p.stem.split('_')[2]; animals[animal]+=1
  loc=strings(f,f['obj/meta/probe/loc']) if 'obj/meta/probe/loc' in f else []
  groups=[o for o in ref_objs(f,f['obj/clu']) if isinstance(o,h5py.Group)]; ns=[]
  for pi,g in enumerate(groups):
   nq=g['quality'].shape[0]; ns.append(nq); rawclus+=nq
   locs[loc[pi] if pi<len(loc) else f'unknown_probe{pi+1}']+=nq
   quals.update(strings(f,g['quality']))
  for k in ['hit','miss','no','R','L','autowater','early']:
   a=np.asarray(f['obj/bp/'+k][()]).ravel(); flags[k]+=int(np.nansum(a)); flags[k+'.nan']+=int(np.isnan(a).sum())
  a=np.asarray(f['obj/bp/stim/enable'][()]).ravel(); flags['stim.enable']+=int(np.nansum(a))
  for k in ['haveEphys','haveVid']:
   a=np.asarray(f['obj/trials/bp/'+k][()]).ravel(); valid[k]+=int(a.sum()); valid[k+'.total']+=a.size
  go=np.asarray(f['obj/bp/ev/goCue'][()]).ravel(); valid['goCue.finite']+=int(np.isfinite(go).sum())
  rows.append((p.stem.replace('data_structure_',''),n,loc or ['unknown']*len(groups),ns))
print('sessions',len(fs),'subjects/sessions',dict(animals),'trials',total_trials,'raw clusters',rawclus)
print('probe loc cluster totals',dict(locs))
print('qualities',dict(quals))
print('flags',dict(flags))
print('valid',dict(valid))
for r in rows: print(r)
PY","workdir":"/app","yield_time_ms":30000,"max_output_tokens":30000});
text(r.output);

