const r = await tools.exec_command({cmd:"python3 - <<'PY'
from pathlib import Path
from collections import Counter
import h5py,numpy as np
from scipy.io import loadmat
root=Path('/app/data'); files=sorted(root.glob('**/data_structure_*.mat'))
trials=Counter(); sessions=Counter(); subjects=Counter(); clusters=Counter()
for ix,p in enumerate(files,1):
 d=p.parent.name; animal=p.name.split('_')[2]; sessions[d]+=1; subjects[animal]+=1
 if h5py.is_hdf5(p):
  with h5py.File(p,'r') as f:
   trials[d]+=int(np.asarray(f['obj/bp/Ntrials'][()]).squeeze())
   if 'obj/clu' in f:
    for r in np.asarray(f['obj/clu'][()]).ravel(order='F'):
     if isinstance(r,h5py.Reference) and r:
      o=f[r]
      if isinstance(o,h5py.Group) and 'quality' in o: clusters[d]+=o['quality'].shape[0]
 else:
  o=loadmat(p,squeeze_me=True,struct_as_record=False,variable_names=['obj'])['obj']
  trials[d]+=int(o.bp.Ntrials)
  if hasattr(o,'clu'):
   cs=np.atleast_1d(o.clu).ravel(); clusters[d]+=sum(hasattr(c,'quality') for c in cs)
