a_x must not be negative!');end;% Check plausibility of given spacingif delta_x>0    temp=sort(x);    temp=diff(temp);    temp=temp(find(temp~=0));    temp=unique(temp); % get all non-zero spacings    temp=temp/delta_x;        if ~isempty(find(temp~=round(temp))) % Are there spacings which are not multiples of the given delta_x?       error('DIP_TEST: The given delta_x is incompatible with x!');    end;end;% Make continuous values from discrete valuesif delta_x>0    x=x+(rand(size(x,1),size(x,2))-.5)*delta_x;end;% Sort the vectorx=sort(x);n=length(x);% Further checksif x(1)==x(n) % all observations identical?    error('DIP_TEST: All observations must not be identical!');end;% Computationlow=1; % lower indexhigh=n; % upper indexdip=1/n;xl=x(low);xu=x(high);% Establish the indices over which combination is necessary for the convex minorant fitmn=1;for j=2:n    mn(j)=j-1;        while 1        mnj=mn(j);        mnmnj=mn(mnj);        a=mnj-mnmnj;        b=j-mnj;                if (mnj==1)|(((x(j)-x(mnj))*a)<((x(mnj)-x(mnmnj))*b))            break;        end;                mn(j)=mnmnj;    end;end;% Establish the indices over which combination is necessary for the concave majorant fitclear mj;mj(n)=n;for jk=1:n-1    k=n-jk;    mj(k)=k+1;        while 1        mjk=mj(k);        mjmjk=mj(mjk);        a=mjk-mjmjk;        b=k-mjk;                if (mjk==n)|(((x(k)-x(mjk))*a)<((x(mjk)-x(mjmjk))*b))            break;        end;               mj(k)=mjmjk;    end;end;% Start the cycling% Collect the change points for the GCM from high to lowclear gcm lcm;while 1 % line 40 in the Fortran algorithm (big loop)    ic=1;    gcm(1)=high;        while 1        igcm1=gcm(ic);        ic=ic+1;        gcm(ic)=mn(igcm1);                if gcm(ic)<=low            break;        end;    end;        icx=ic;        % Collect the change points for the LCM from low to high    ic=1;    lcm(1)=low;    